      myCommentBgHex: '#007acc',
      myCommentBgOpacity: 0.1,

      genericCommentBgHex: '#000000', // Black
      genericCommentBgOpacity: 0.65,

      // --- Layout ---
      indentation: 35,
      verticalPadding: 15,
      commentContentMarginLeft: 4,
      avatarMarginTop: 2,
